import{z as o,x as i,o as e,c as s,q as B,j as t,D as a,d as r,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"模型风险治理的深化","description":"","frontmatter":{"title":"模型风险治理的深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rk-model-governance-deep.md","filePath":"quant/rk-model-governance-deep.md","lastUpdated":1791063341000}'),d={name:"quant/rk-model-governance-deep.md"};function p(C,E,m,_,F,c){const A=i("Mermaid");return e(),s("div",null,[E[2]||(E[2]=B('<h1 id="模型风险治理的深化" tabindex="-1">模型风险治理的深化 <a class="header-anchor" href="#模型风险治理的深化" aria-label="Permalink to &quot;模型风险治理的深化&quot;">​</a></h1><div class="epigraph"><p>模型风险有两个来源：错的模型，与对模型的错用；验证负责让第一种现形，治理负责让第二种无路可走。</p><footer>—— 据 Federal Reserve SR 11-7（2011）；Cont, *Model uncertainty and its impact on the pricing of derivative instruments*, Mathematical Finance, 2006 整理</footer></div><p><a href="/quant/rk-operational">上一课</a>收掉计量单元：市场、流动性、对手方、操作四类损失各有生成机制与数据。四类计量的每一环都依赖模型，模型本身的错误谁来管，是治理单元的第一课。<a href="/quant/sr-11-7-model-risk">SR 11-7 模型风险管理</a>已交代定义、三根柱子与有效挑战；本课深化落地层：模型库与分级、验证做什么、清单之外的实践——尤其共享假设与机器学习管道。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>原则到落地之间的缺口有四处。模型库不完整：研究代码、临时脚本直接喂进决策，库里查无此模型，验证无从谈起。分级不分材质：把关键定价模型与辅助报表模型塞进同一流程，要么重流程拖死业务，要么轻流程放走要害。验证退化成复算：拿开发者的代码再跑一遍、对了就算过——没有独立基准、没有结果分析，等于让被验证者自证。变更管理断裂：模型的输入、用途或市场变了，验证状态却挂在旧版本上，证书过期还挂着上岗。四类缺口共享一个后果：决策层以为有模型在管，实际没人知道假设走到哪了。</p><p><span class="marginnote">术语翻译：材料性分级就是「这个模型错了会有多疼」——按使用后果排等级：进资本、进限额、进客户报价的算关键级，验证要独立、要深；只出内部报表的算辅助级，轻量核查即可。疼得越狠，查得越狠。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地从一张库开始：每个模型登记所有者、用途、输入数据、材料性分级、验证状态与复验周期；分级按使用后果定——进资本、进限额、进客户报价的验证深度递增，出报告的做轻量核查。独立验证做三件事：概念健全性——假设、推导与适用域逐条过；基准对照——独立实现、闭式解或另一族模型的结果差，差值要归因；结果分析——回测、后验与损益解释，对接日常监测。持续监测设阈值：输入漂移、校准残差、损益偏差越线即触发复验，不等周期。例外与豁免一律登记并带期限。机器学习与生成式系统只要输出进决策，就按同一套原则登记分级；管道的特殊部位是数据合同与特征监控，验证要点延伸到<a href="/quant/fml-audit">ML 审计</a>的处理：特征血缘、训练数据版本、可复现的评估。</p>',8)),(e(),t(l,null,{default:a(()=>[n(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%7B%22%E4%B8%80%E4%B8%AA%E5%AE%9A%E4%BB%B7%E6%A8%A1%E5%9E%8B%E7%94%B3%E8%AF%B7%E8%BF%9B%E5%BA%93%22%7D%0A%20%20M%20--%3E%20C%5B%22%E6%A6%82%E5%BF%B5%E5%81%A5%E5%85%A8%E6%80%A7%EF%BC%9A%E5%81%87%E8%AE%BE%E3%80%81%E6%8E%A8%E5%AF%BC%E3%80%81%E9%80%82%E7%94%A8%E5%9F%9F%E9%80%90%E6%9D%A1%E8%BF%87%22%5D%0A%20%20M%20--%3E%20B%5B%22%E5%9F%BA%E5%87%86%E5%AF%B9%E7%85%A7%EF%BC%9A%E7%8B%AC%E7%AB%8B%E5%AE%9E%E7%8E%B0%E6%88%96%E9%97%AD%E5%BC%8F%E8%A7%A3%EF%BC%8C%E5%B7%AE%E5%80%BC%E8%A6%81%E5%BD%92%E5%9B%A0%22%5D%0A%20%20M%20--%3E%20R%5B%22%E7%BB%93%E6%9E%9C%E5%88%86%E6%9E%90%EF%BC%9A%E5%9B%9E%E6%B5%8B%E3%80%81%E5%90%8E%E9%AA%8C%E3%80%81%E6%8D%9F%E7%9B%8A%E8%A7%A3%E9%87%8A%22%5D%0A%20%20C%20--%3E%20V%7B%22%E5%B7%AE%E5%80%BC%E5%8F%AF%E5%BD%92%E5%9B%A0%E4%B8%94%E5%9C%A8%E5%AE%B9%E5%BF%8D%E5%86%85%EF%BC%9F%22%7D%0A%20%20B%20--%3E%20V%0A%20%20R%20--%3E%20V%0A%20%20V%20--%20%22%E8%83%BD%22%20--%3E%20U%5B%22%E6%8C%89%E6%9D%90%E6%96%99%E6%80%A7%E5%88%86%E7%BA%A7%E6%8A%95%E5%85%A5%E4%BD%BF%E7%94%A8%E5%B9%B6%E7%9B%91%E6%B5%8B%22%5D%0A%20%20V%20--%20%22%E4%B8%8D%E8%83%BD%22%20--%3E%20X%5B%22%E9%80%80%E5%9B%9E%E5%BC%80%E5%8F%91%EF%BC%8C%E8%B1%81%E5%85%8D%E9%A1%BB%E7%99%BB%E8%AE%B0%E5%B8%A6%E6%9C%9F%E9%99%90%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<p><span class="marginnote">直觉类比：独立验证像请外校老师命题阅卷——不是不信任任课老师，而是同一套思路检查同一套思路，会漏掉同一处盲区。独立基准（闭式解、另一族模型）就是那道「外校题」：两个答案差得远时，先查的是两者共享的假设。</span></p><p><span class="marginnote">共享假设是一个故障域：估值、限额、资本三套模型若共用同一条供应商曲线，曲线日终异常当天三者同时失真——治理视角下这不是三个模型各犯小错，而是同一个假设在库里没有复用登记。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么治理是体系而非文档：模型库把「哪些决策靠哪些假设」变成可审计的映射，审查者顺着库能从一纸报告走到数据源，也能反向找出所有用同一数据的模型——这是发现共享假设与加总风险的唯一入口。分散在各系统的影子模型没有这个性质，出事时连受影响范围都点不清。为什么验证强调独立：有效挑战的价值在视角差，不在二次计算；独立实现的对价是慢与贵，材料性分级就是把这份贵花在要害上。Cont 的提醒是边界：模型不确定性的定价差距可以估计，但「正确模型」不存在，治理只能保证模型被知晓、被验证、被限制用途，不保证模型对。</p><p><span class="marginnote">常见误区：把验证当成一次性盖章。模型的环境会变——输入数据换了供应商、用途从定价挪到资本、市场结构变了，旧证书就不再描述眼前的模型。验证状态必须与版本和用途绑定，变更即触发复验，没有终身免检。</span></p>',5)),(e(),t(l,null,{default:a(()=>[n(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E6%A8%A1%E5%9E%8B%E7%99%BB%E8%AE%B0%EF%BC%9Aowner%20%E4%B8%8E%E7%94%A8%E9%80%94%22%5D%20--%3E%20TIER%5B%22%E6%9D%90%E6%96%99%E6%80%A7%E5%88%86%E7%BA%A7%22%5D%0A%20%20TIER%20--%3E%20VAL%5B%22%E7%8B%AC%E7%AB%8B%E9%AA%8C%E8%AF%81%EF%BC%9A%E6%A6%82%E5%BF%B5%E3%80%81%E5%9F%BA%E5%87%86%E3%80%81%E7%BB%93%E6%9E%9C%22%5D%0A%20%20VAL%20--%3E%20USE%5B%22%E6%8A%95%E5%85%A5%E4%BD%BF%E7%94%A8%E5%B9%B6%E6%8C%81%E7%BB%AD%E7%9B%91%E6%B5%8B%22%5D%0A%20%20USE%20--%3E%7C%22%E9%98%88%E5%80%BC%E8%B6%8A%E7%BA%BF%22%7C%20REVAL%5B%22%E8%A7%A6%E5%8F%91%E5%A4%8D%E9%AA%8C%22%5D%0A%20%20USE%20--%3E%7C%22%E7%94%A8%E9%80%94%E6%88%96%E8%BE%93%E5%85%A5%E5%8F%98%E6%9B%B4%22%7C%20REVAL%0A%20%20REVAL%20--%3E%20USE%0A%20%20TIER%20--%3E%20X%5B%22%E8%B1%81%E5%85%8D%E7%99%BB%E8%AE%B0%EF%BC%9A%E5%B8%A6%E6%9C%9F%E9%99%90%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重述 SR 11-7 的模型定义与三根柱子，也不做单一模型的数值校准验证——定价模型的校准诊断在定价深化课程处理。治理与操作风险的边界按错误性质分：概念错归模型风险，运行错归操作风险；这条分界决定改进流向，模糊不得。相称性原则调节验证强度，不豁免登记义务——小模型可以验证得轻，不能库里没有。ML 管道的验证深度尚无定论，可解释性与稳定性是当前最弱的格，与其宣称已覆盖，不如在分级里显式降级使用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模型治理的第一对象是库：登记不完整的机构谈不上模型风险管理。</li><li>材料性分级把验证的独立性与深度分配到要害；验证是概念、基准、结果三件事。</li><li>持续监测与变更触发复验，验证状态与模型版本绑定，没有永久证书。</li><li>共享假设要在库层面登记，它把多个模型的失败连成一个故障域。</li><li>出处：Federal Reserve SR 11-7 与 OCC Bulletin 2011-12；Cont, <em>Mathematical Finance</em>, 2006；机器学习管道的审计要点见本站 ML 审计与 SR 11-7 两课。</li></ul>',4))])}const u=o(d,[["render",p]]);export{h as __pageData,u as default};
